-- Official client field normalization. Source facts and row changes are recorded in Gameforge/normalization/.
USE [TGame_gsp];
GO
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO
BEGIN TRANSACTION;
DECLARE @changed INT=0;
CREATE TABLE #GfChange0 (Id SMALLINT PRIMARY KEY,BeforeValue TINYINT NULL,AfterValue TINYINT NULL);
INSERT #GfChange0 VALUES (11984,1,0),
