IF EXISTS(SELECT 1 FROM #GfChange0 r LEFT JOIN dbo.[TITEMCHART] t ON t.[wItemID]=r.Id WHERE t.[wItemID] IS NULL OR NOT(((t.[bCanColor] IS NOT NULL AND r.BeforeValue IS NOT NULL AND t.[bCanColor]=r.BeforeValue) OR (t.[bCanColor] IS NULL AND r.BeforeValue IS NULL)) OR ((t.[bCanColor] IS NOT NULL AND r.AfterValue IS NOT NULL AND t.[bCanColor]=r.AfterValue) OR (t.[bCanColor] IS NULL AND r.AfterValue IS NULL)))) THROW 51000,'Gameforge normalization baseline changed: TITEMCHART.bCanColor',1;
UPDATE t SET [bCanColor]=r.AfterValue FROM dbo.[TITEMCHART] t JOIN #GfChange0 r ON t.[wItemID]=r.Id WHERE NOT ((t.[bCanColor] IS NOT NULL AND r.AfterValue IS NOT NULL AND t.[bCanColor]=r.AfterValue) OR (t.[bCanColor] IS NULL AND r.AfterValue IS NULL));
SET @changed=@changed+@@ROWCOUNT;
IF EXISTS(SELECT 1 FROM #GfChange0 r JOIN dbo.[TITEMCHART] t ON t.[wItemID]=r.Id WHERE NOT ((t.[bCanColor] IS NOT NULL AND r.AfterValue IS NOT NULL AND t.[bCanColor]=r.AfterValue) OR (t.[bCanColor] IS NULL AND r.AfterValue IS NULL))) THROW 51000,'Gameforge normalization postcondition failed: TITEMCHART.bCanColor',1;
DROP TABLE #GfChange0;
