IF EXISTS(SELECT 1 FROM #GfChange17 r LEFT JOIN dbo.[TITEMCHART] t ON t.[wItemID]=r.Id WHERE t.[wItemID] IS NULL OR NOT(((t.[fPrice] IS NOT NULL AND r.BeforeValue IS NOT NULL AND CONVERT(REAL,t.[fPrice])=CONVERT(REAL,r.BeforeValue)) OR (t.[fPrice] IS NULL AND r.BeforeValue IS NULL)) OR ((t.[fPrice] IS NOT NULL AND r.AfterValue IS NOT NULL AND CONVERT(REAL,t.[fPrice])=CONVERT(REAL,r.AfterValue)) OR (t.[fPrice] IS NULL AND r.AfterValue IS NULL)))) THROW 51000,'Gameforge normalization baseline changed: TITEMCHART.fPrice',1;
UPDATE t SET [fPrice]=r.AfterValue FROM dbo.[TITEMCHART] t JOIN #GfChange17 r ON t.[wItemID]=r.Id WHERE NOT ((t.[fPrice] IS NOT NULL AND r.AfterValue IS NOT NULL AND CONVERT(REAL,t.[fPrice])=CONVERT(REAL,r.AfterValue)) OR (t.[fPrice] IS NULL AND r.AfterValue IS NULL));
SET @changed=@changed+@@ROWCOUNT;
IF EXISTS(SELECT 1 FROM #GfChange17 r JOIN dbo.[TITEMCHART] t ON t.[wItemID]=r.Id WHERE NOT ((t.[fPrice] IS NOT NULL AND r.AfterValue IS NOT NULL AND CONVERT(REAL,t.[fPrice])=CONVERT(REAL,r.AfterValue)) OR (t.[fPrice] IS NULL AND r.AfterValue IS NULL))) THROW 51000,'Gameforge normalization postcondition failed: TITEMCHART.fPrice',1;
DROP TABLE #GfChange17;
CREATE TABLE #GfChange18 (Id SMALLINT PRIMARY KEY,BeforeValue nvarchar(100) COLLATE DATABASE_DEFAULT NULL,AfterValue nvarchar(100) COLLATE DATABASE_DEFAULT NULL);
