IF EXISTS(SELECT 1 FROM #GfChange18 r LEFT JOIN dbo.[TITEMCHART] t ON t.[wItemID]=r.Id WHERE t.[wItemID] IS NULL OR NOT(((t.[szNAME] IS NOT NULL AND r.BeforeValue IS NOT NULL AND CONVERT(VARBINARY(MAX),t.[szNAME])=CONVERT(VARBINARY(MAX),r.BeforeValue)) OR (t.[szNAME] IS NULL AND r.BeforeValue IS NULL)) OR ((t.[szNAME] IS NOT NULL AND r.AfterValue IS NOT NULL AND CONVERT(VARBINARY(MAX),t.[szNAME])=CONVERT(VARBINARY(MAX),r.AfterValue)) OR (t.[szNAME] IS NULL AND r.AfterValue IS NULL)))) THROW 51000,'Gameforge normalization baseline changed: TITEMCHART.szNAME',1;
UPDATE t SET [szNAME]=r.AfterValue FROM dbo.[TITEMCHART] t JOIN #GfChange18 r ON t.[wItemID]=r.Id WHERE NOT ((t.[szNAME] IS NOT NULL AND r.AfterValue IS NOT NULL AND CONVERT(VARBINARY(MAX),t.[szNAME])=CONVERT(VARBINARY(MAX),r.AfterValue)) OR (t.[szNAME] IS NULL AND r.AfterValue IS NULL));
SET @changed=@changed+@@ROWCOUNT;
IF EXISTS(SELECT 1 FROM #GfChange18 r JOIN dbo.[TITEMCHART] t ON t.[wItemID]=r.Id WHERE NOT ((t.[szNAME] IS NOT NULL AND r.AfterValue IS NOT NULL AND CONVERT(VARBINARY(MAX),t.[szNAME])=CONVERT(VARBINARY(MAX),r.AfterValue)) OR (t.[szNAME] IS NULL AND r.AfterValue IS NULL))) THROW 51000,'Gameforge normalization postcondition failed: TITEMCHART.szNAME',1;
DROP TABLE #GfChange18;
CREATE TABLE #GfChange19 (Id SMALLINT PRIMARY KEY,BeforeValue SMALLINT NULL,AfterValue SMALLINT NULL);
